import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import humanTime from 'flarum/common/helpers/humanTime';
import { placeUrl, statusBadge, reasonLabel } from '../labels';
import { t } from '../t';

/**
 * The posts you reported and how each report went, as far as staff chose to
 * tell you.
 */
export default class MyReportsPage extends Page {
  entries = [];
  loading = true;
  more = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.session.user) {
      m.route.set(app.route('index'));
      return;
    }
    app.setTitle(t('mine.title'));
    this.load(0);
  }
  load(offset) {
    this.loading = true;
    app.store.find('docket-entries', {
      page: {
        offset,
        limit: 20
      }
    }).then(entries => {
      this.entries.push(...entries);
      this.more = !!entries.payload?.links?.next;
    }).catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "DocketPage DocketMinePage"
    }, m("div", {
      className: "container"
    }, m("h2", {
      className: "DocketPage-title"
    }, t('mine.title')), m("p", {
      className: "DocketPage-intro"
    }, t('mine.intro')), !this.loading && !this.entries.length ? m(Placeholder, {
      text: t('mine.empty')
    }) : null, m("ul", {
      className: "DocketMine"
    }, this.entries.map(entry => {
      const place = entry.place();
      return m("li", {
        className: "DocketCard DocketMine-item",
        key: entry.id()
      }, m("div", {
        className: "DocketMine-head"
      }, statusBadge(entry.reportStatus()), m("span", {
        className: "DocketMine-when"
      }, humanTime(entry.createdAt()))), m("div", {
        className: "DocketMine-what"
      }, place ? m(Link, {
        href: placeUrl(place)
      }, place.title) : m("span", {
        className: "DocketMine-gone"
      }, t('mine.post_unavailable'))), m("div", {
        className: "DocketMine-reason"
      }, t('mine.your_reason'), " ", reasonLabel(entry), entry.reasonDetail() ? m("span", {
        className: "DocketMine-detail"
      }, " \u2014 ", entry.reasonDetail()) : null), entry.outcome() ? m("blockquote", {
        className: "DocketMine-outcome"
      }, entry.outcome()) : null);
    })), this.loading ? m(LoadingIndicator, null) : null, this.more && !this.loading ? m("div", {
      className: "DocketList-more"
    }, m(Button, {
      className: "Button",
      onclick: () => this.load(this.entries.length)
    }, t('list.load_more'))) : null));
  }
}
flarum.reg.add('ernestdefoe-docket', 'forum/components/MyReportsPage', MyReportsPage);